    async def list(
        self,
        *,
        start_time: dt.datetime,
        end_time: dt.datetime,
        cursor: typing.Optional[str] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncPager[Issue, GetIssuesResponseBody]:
        """
        Returns a paginated list of issues created within a required time range (max 365 days). Results are sorted by created_at, newest first. To filter on updated_at or other timestamps, use POST /issues/search.

        **Rate limit:** 30 requests per minute

        Parameters
        ----------
        start_time : dt.datetime
            The start of the time range, filtering on the issue's created_at (inclusive). Use RFC3339 with Z or a URL-encoded offset (%2B). The duration between start_time and end_time must be less than or equal to 365 days.

        end_time : dt.datetime
            The end of the time range, filtering on the issue's created_at (exclusive). Use RFC3339 with Z or a URL-encoded offset (%2B). The duration between start_time and end_time must be less than or equal to 365 days.

        cursor : typing.Optional[str]
            The cursor to use for pagination.

        limit : typing.Optional[int]
            The number of issues to fetch. Defaults to 20000. Set to 0 or omit to use the default. Must be between 0 and 20000.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncPager[Issue, GetIssuesResponseBody]


        Examples
        --------
        import asyncio
        import datetime

        from usepylon import AsyncPylon

        client = AsyncPylon(
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            response = await client.issues.list(
                start_time=datetime.datetime.fromisoformat(
                    "2024-01-15 09:30:00+00:00",
                ),
                end_time=datetime.datetime.fromisoformat(
                    "2024-01-15 09:30:00+00:00",
                ),
            )
            async for item in response:
                yield item

            # alternatively, you can paginate page-by-page
            async for page in response.iter_pages():
                yield page


        asyncio.run(main())
        """
        return await self._raw_client.list(
            start_time=start_time, end_time=end_time, cursor=cursor, limit=limit, request_options=request_options
        )

